; Generated by c64-source. Edit the values here: generate keeps them.
; The switches of the build. Each switch is 0 or 1: change a value, then build again.
; The defaults give the clean program: copy protection, trainers, cheats and
; changes of a crack are 0, and the fixes of the releases are 1.
; generate adds a new switch with its default and removes a switch that the
; knowledge does not have. The build of a release does not read this file.

; Trainers: off by default
TRAINER_DOG_TOLERANCE = 0 ; on in HF_TRAINERS. $9624-$9625. Hokuto Force trainer: infinite dog tolerance
TRAINER_HYPERSPEED    = 0 ; on in HF_TRAINERS. $9082-$9084. Hokuto Force trainer: hyperspeed mower (the main loop skips its delay)
TRAINER_INVINCIBLE    = 0 ; on in HF_TRAINERS. $9718-$9719. Hokuto Force trainer: invincibility
TRAINER_LIVES         = 0 ; on in HF_TRAINERS. $98b9-$98ba. Hokuto Force trainer: infinite lives
TRAINER_NO_OVERLOAD   = 0 ; on in HF_TRAINERS. $9234-$9235. Hokuto Force trainer: no mower overload
TRAINER_SKIP_LEVEL    = 0 ; on in HF_TRAINERS. $917a-$917c. Hokuto Force trainer: key S skips the lawn. It calls a routine at $2a00 of the HF trainer code, outside the MAIN block

; Changes of a crack: off by default
CRACK_HF              = 0 ; on in HF, HF_SCORES, HF_TRAINERS. $63c0-$63ff, $6400-$67ff, $6800-$6a9b, $6a9c-$6bfd, $6bfe-$6bff, $6c00-$7bff, $7ddb-$7ddf, $7dfd-$7dfd, $7e00-$7e2e, $7e2f-$7e31, $7e32-$7e62, $7e63-$7fff, $8000-$8009, $9fd6-$9fff. Hokuto Force: $ff fill over the packed data, its saver code at $7e00, the start without the unpack
CRACK_HF_MENU         = 0 ; on in HF, HF_TRAINERS. $9fd5-$9fd5. Hokuto Force: the menu stores its answer (T) at $9fd5, a free byte
CRACK_HF_SCORES       = 0 ; on in HF_SCORES. $9f9d-$9f9f, $9fd5-$9fd5. Hokuto Force high-score saver (menu answer H): the high-score entry calls the save routine at $7e79. Needs CRACK_HF.
CRACK_KSX_RELOCATE    = 0 ; on in KSX. $6a9c-$6bfd, $7e2f-$7e31, $922c-$922d, $9fd6-$9fff. Kraksnax: the unpack copies the last charset page to $0b04, and a relocation of that page also changed 2 bytes of the table at $922b
CRACK_KSX_TEXTS       = 0 ; on in KSX. $7cca-$7cdd, $83ae-$83d4, $89ef-$89f1, $8ab6-$8ac1, $9a8c-$9a93, $9ab1-$9ab6, $9b48-$9d04, $9e46-$9e74. Kraksnax: the "US/Canadian edition" texts, the lenders Doc, Mo and Jo, and the high-score names

; Leftovers: off by default
LEFTOVERS = 0 ; 1 bytes in 1 file in leftovers/ that nothing uses. 1 builds them, so main.asm gives the bytes of the program. Each release has them. The loader never loads them
